import numpy as np

def jacobi_matrix_eigs(N):
    """eigenvalues of R = I - D^-1 (-A) for the open N x N 5-point Laplacian"""
    n = N * N
    A = np.zeros((n, n))
    for j in range(N):
        for i in range(N):
            c = j * N + i
            A[c, c] = -4.0
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                if 0 <= i + di < N and 0 <= j + dj < N:
                    A[c, (j + dj) * N + i + di] = 1.0
    R = np.eye(n) + A / 4.0                      # I - D^-1 (-A) with D = -4 I ... R = I + A/4
    return np.linalg.eigvals(R).real

for N in (6, 8, 12):
    rho = np.max(np.abs(jacobi_matrix_eigs(N)))
    print(N, rho, np.cos(np.pi / (N + 1)), "sweeps for 1e-3:", np.log(1e-3) / np.log(rho))
